package net.civeira.phylax.feature.observe.observedalert.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedalert.domain.ObservedAlert;
import net.civeira.phylax.feature.observe.observedalert.domain.valueobject.ProblemKeyVO;

class ProblemKeyValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of problem key of observed alert")
  void test_problem_key_value_holder_assign_plain_value() {
    Object holder = new Object();
    ProblemKeyValueHolder<Object> value = new ProblemKeyValueHolder<>(holder);
    Assertions.assertSame(holder, value.problemKey("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getProblemKeyValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getProblemKey().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of problem key of observed alert")
  void test_problem_key_value_holder_assign_value_object() {
    Object holder = new Object();
    ProblemKeyValueHolder<Object> value = new ProblemKeyValueHolder<>(holder);
    ProblemKeyVO vo = ProblemKeyVO.from("one");
    Assertions.assertFalse(value.getProblemKeyValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.problemKey(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getProblemKeyValue().orElseThrow());
    Assertions.assertSame(holder, value.problemKey(Optional.empty()));
    Assertions.assertFalse(value.getProblemKeyValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.problemKey(Optional.of(vo)));
    Assertions.assertSame(vo, value.getProblemKeyValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of problem key of observed alert against the original")
  void test_problem_key_value_holder_read() {
    Object holder = new Object();
    ProblemKeyValueHolder<Object> value = new ProblemKeyValueHolder<>(holder);
    ProblemKeyVO vo = ProblemKeyVO.from("one");
    ProblemKeyVO other = ProblemKeyVO.from("one");
    ObservedAlert original = Mockito.mock(ObservedAlert.class);
    Mockito.when(original.getProblemKeyValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readProblemKey(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readProblemKey(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.problemKey(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readProblemKey(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readProblemKey(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of problem key of observed alert")
  void test_problem_key_value_holder_unset() {
    Object holder = new Object();
    ProblemKeyValueHolder<Object> value = new ProblemKeyValueHolder<>(holder);
    ProblemKeyVO vo = ProblemKeyVO.from("one");
    value.problemKey(vo);
    Assertions.assertSame(holder, value.unsetProblemKeyIfMatches("problemKey_other"));
    Assertions.assertTrue(value.getProblemKeyValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetProblemKeyIfMatches("problemKey"));
    Assertions.assertFalse(value.getProblemKeyValue().isPresent(),
        "The field name must clear the value");
    value.problemKey(vo);
    Assertions.assertSame(holder, value.unsetProblemKey());
    Assertions.assertFalse(value.getProblemKeyValue().isPresent(), "Unset must clear the value");
  }
}
